import { useCallback, useState } from 'react';
import { useFocusEffect } from '@react-navigation/native';
import type { NativeStackScreenProps } from '@react-navigation/native-stack';
import { ActivityIndicator, FlatList, StyleSheet, Text, View } from 'react-native';

import { client } from '../api/client';
import type { Chat } from '../api/types';
import { ChatListItem, getChatTitle } from '../components/ChatListItem';
import type { RootStackParamList } from '../navigation/types';
import { theme } from '../theme';

type Props = NativeStackScreenProps<RootStackParamList, 'ChatList'>;

type Palette = {
  bg: string;
  accent: string;
  muted?: string;
  textMuted?: string;
  danger?: string;
};

const themeValue = theme as unknown as Palette & { colors?: Palette };
const colors = themeValue.colors ?? themeValue;
const mutedColor = colors.textMuted ?? colors.muted ?? '#8B9BB4';

function normalizeChats(response: unknown): Chat[] {
  if (Array.isArray(response)) return response as Chat[];

  if (response && typeof response === 'object' && 'chats' in response) {
    const chats = (response as { chats?: unknown }).chats;
    return Array.isArray(chats) ? (chats as Chat[]) : [];
  }

  return [];
}

function getChatId(chat: Chat) {
  return String((chat as unknown as { id: string }).id);
}

export function ChatListScreen({ navigation }: Props) {
  const [chats, setChats] = useState<Chat[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadChats = useCallback(async (refresh = false) => {
    if (refresh) setRefreshing(true);
    else setLoading(true);
    setError(null);

    try {
      setChats(normalizeChats(await client.listChats()));
    } catch (caughtError) {
      setError(caughtError instanceof Error ? caughtError.message : 'Не удалось загрузить чаты');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useFocusEffect(
    useCallback(() => {
      void loadChats();
    }, [loadChats]),
  );

  if (loading && chats.length === 0) {
    return (
      <View style={styles.centered}>
        <ActivityIndicator color={colors.accent} size="large" />
      </View>
    );
  }

  return (
    <View style={styles.screen}>
      {error ? <Text style={styles.error}>{error}</Text> : null}
      <FlatList
        contentContainerStyle={chats.length === 0 ? styles.emptyList : undefined}
        data={chats}
        keyExtractor={getChatId}
        ListEmptyComponent={<Text style={styles.emptyText}>Нет чатов — нажмите +</Text>}
        onRefresh={() => void loadChats(true)}
        refreshing={refreshing}
        renderItem={({ item }) => {
          const title = getChatTitle(item);
          const chatId = getChatId(item);
          return (
            <ChatListItem
              chat={item}
              onPress={() => navigation.navigate('Chat', { chatId, title })}
            />
          );
        }}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { backgroundColor: colors.bg, flex: 1 },
  centered: {
    alignItems: 'center',
    backgroundColor: colors.bg,
    flex: 1,
    justifyContent: 'center',
  },
  emptyList: {
    flexGrow: 1,
    justifyContent: 'center',
    paddingHorizontal: 24,
  },
  emptyText: { color: mutedColor, fontSize: 15, textAlign: 'center' },
  error: {
    color: colors.danger ?? '#FF6B6B',
    fontSize: 13,
    paddingHorizontal: 16,
    paddingVertical: 10,
    textAlign: 'center',
  },
});
